package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.http.MediaType;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app"}) @AutoConfigureMockMvc class CouponHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean CouponInventory service;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);var b=Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").expiresAt(Instant.now().plusSeconds(600));if(t.equals("owner"))b.claim("subject_type","user").claim("role","OWNER").claim("app_id","test-app");else if(t.equals("operator"))b.claim("subject_type","operator_account").claim("role","OPERATOR").claim("app_id","operator-account");else b.claim("subject_type","staff_account").claim("role","MERCHANT").claim("app_id","merchant-account").claim("merchant_id",1L);return b.build();});}
 @Test void authRolesAndPrivateRead()throws Exception{mvc.perform(get("/api/coupon/mine")).andExpect(status().isUnauthorized());mvc.perform(get("/api/coupon/mine").header("Authorization","Bearer merchant")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/coupons").header("Authorization","Bearer owner")).andExpect(status().isForbidden());when(service.mine(any(),eq(1),eq(20))).thenReturn(Map.of("items",List.of(),"total",0,"page",1,"page_size",20));mvc.perform(get("/api/coupon/mine").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}
 @Test void strictQueriesRejectForgeryAndDuplicates()throws Exception{for(String q:List.of("user_id=2","page=01","page=1&page=2","page_size=101","merchant_id=1"))mvc.perform(get("/api/coupon/mine?"+q).header("Authorization","Bearer owner")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void claimRequiresCanonicalBodyAndUuid()throws Exception{for(String b:List.of("null","{}","{\"coupon_id\":1,\"publication_revision\":2,\"user_id\":3}","{\"coupon_id\":1,\"coupon_id\":2,\"publication_revision\":2}","{\"coupon_id\":1,\"publication_revision\":2}{}","{\"coupon_id\":\"1\",\"publication_revision\":2}"))mvc.perform(post("/api/coupon/receive").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(post("/api/coupon/receive").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{\"coupon_id\":1,\"publication_revision\":2}")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void monetaryAndServiceRulesFailClosed()throws Exception{var json=new com.fasterxml.jackson.databind.ObjectMapper();var terms=json.createObjectNode().put("name","测试券").put("type","DISCOUNT").put("project_id",1).put("amount","5.00").put("min_spend","10.00").put("total_quantity",1).put("valid_from","2026-10-14T00:00:00Z").put("valid_to","2026-10-15T00:00:00Z");var valid=json.createObjectNode();valid.set("terms",terms);for(String field:List.of("amount","min_spend","total_quantity","valid_to","type")){var bad=valid.deepCopy();switch(field){case "amount"->((com.fasterxml.jackson.databind.node.ObjectNode)bad.get("terms")).put(field,5.0);case "min_spend"->((com.fasterxml.jackson.databind.node.ObjectNode)bad.get("terms")).put(field,"1.00");case "total_quantity"->((com.fasterxml.jackson.databind.node.ObjectNode)bad.get("terms")).put(field,0);case "valid_to"->((com.fasterxml.jackson.databind.node.ObjectNode)bad.get("terms")).put(field,"2026-10-13T00:00:00Z");default->((com.fasterxml.jackson.databind.node.ObjectNode)bad.get("terms")).put(field,"SERVICE");}mvc.perform(post("/api/merchant/coupons").header("Authorization","Bearer merchant").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(bad.toString())).andExpect(status().isBadRequest());}verifyNoInteractions(service);}
 @Test void backendFailureHidesSql()throws Exception{when(service.mine(any(),anyInt(),anyInt())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL"));mvc.perform(get("/api/coupon/mine").header("Authorization","Bearer owner")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.message").value("券服务暂不可用，请重试"));}
}
